          "സെക്ഷൻ 112A: ഇക്വിറ്റി ഫണ്ട് യൂണിറ്റുകളിലെ ദീർഘകാല നേട്ടങ്ങൾക്ക് 10%, 23 Jul 2024 മുതലുള്ള വിൽപ്പനകൾക്ക് 12.5%, പ്രതിവർഷം Rs 1 lakh ഇളവിന് മുകളിൽ, FY 2024-25 മുതൽ Rs 1.25 lakh. FY 2024-25-ൽ Rs 1.25 lakh രണ്ട് നിരക്കുകൾക്കും കൂടി ഒരൊറ്റ പരിധിയാണ്; ഏത് നേട്ടങ്ങൾക്ക് ആദ്യം ബാധകമാണെന്ന് നിയമം പറയുന്നില്ല, അതിനാൽ ഇത് 12.5% നേട്ടങ്ങൾക്ക് പ്രയോഗിക്കുന്നു, ചെലവ് കുറഞ്ഞ തിരഞ്ഞെടുപ്പ്. ഇത് 1 Apr 2018 മുതലുള്ള വിൽപ്പനകൾക്ക് ടാക്സ് ചുമത്തുന്നു; അതിന് മുമ്പ് സെക്ഷൻ 10(38) അവയ്ക്ക് ഇളവ് നൽകിയിരുന്നു, അതിനാൽ മുൻ വർഷങ്ങൾ ടാക്സ് ഇല്ലാതെ കാണിക്കുന്നു.",
        grandfathering:
          "Grandfathering: 1 Feb 2018-ന് മുമ്പ് വാങ്ങിയ ഇക്വിറ്റി യൂണിറ്റുകൾക്ക്, ചെലവ് എന്നത് യഥാർത്ഥ ചെലവും, 31 Jan 2018-ലെ മൂല്യവും വിൽപ്പന മൂല്യവും തമ്മിൽ കുറഞ്ഞതും, ഇവയിൽ കൂടിയതാണ്. ആ മൂല്യം 31 Jan 2018-ലെ NAV ആണ്, ലിസ്റ്റ് ചെയ്ത യൂണിറ്റിന് അന്ന് ട്രേഡ് ചെയ്ത ഏറ്റവും ഉയർന്ന വില.",
        s112: "സെക്ഷൻ 112: മറ്റ് യൂണിറ്റുകളിലെ ദീർഘകാല നേട്ടങ്ങൾക്ക് 23 Jul 2024-ന് മുമ്പുള്ള വിൽപ്പനകൾക്ക് ഇൻഡക്സേഷനോടെ 20% (cost inflation index, അടിസ്ഥാനം 2001-02 = 100), ആ തീയതി മുതൽ ഇൻഡക്സേഷനില്ലാതെ 12.5%. ഈ യൂണിറ്റുകളിലെ ഹ്രസ്വകാല നേട്ടങ്ങൾക്ക് സ്ലാബ് നിരക്കിൽ ടാക്സ്.",
        s50AA:
          "സെക്ഷൻ 50AA (Finance Act 2023): 1 Apr 2023-നോ അതിന് ശേഷമോ വാങ്ങിയ specified mutual fund യൂണിറ്റുകളിലെ നേട്ടങ്ങൾ എത്ര കാലം കൈവശം വച്ചാലും ഹ്രസ്വകാലമാണ്, സ്ലാബ് നിരക്കിൽ. FY 2024-25 വരെ specified fund എന്നാൽ ഇന്ത്യൻ ഇക്വിറ്റിയിൽ 35%-ൽ കൂടാത്തത്, ഇതിൽ ഗോൾഡ്, സിൽവർ, ഇന്റർനാഷണൽ ഫണ്ടുകൾ പെട്ടിരുന്നു. Finance (No. 2) Act 2024 ഇത് FY 2025-26 മുതൽ ഡെറ്റിലും മണി മാർക്കറ്റ് ഇൻസ്ട്രുമെന്റുകളിലും 65%-ൽ കൂടുതലുള്ള ഫണ്ടുകളിലേക്കോ, അത്തരം ഫണ്ടുകളിൽ 65% അല്ലെങ്കിൽ അതിലധികമുള്ളവയിലേക്കോ ചുരുക്കി.",
        equityOriented:
          "ഇക്വിറ്റി ഫണ്ട് (equity-oriented): പണത്തിന്റെ കുറഞ്ഞത് 65% ലിസ്റ്റ് ചെയ്ത ഇന്ത്യൻ ഇക്വിറ്റിയിൽ, അല്ലെങ്കിൽ ലിസ്റ്റ് ചെയ്ത ഇന്ത്യൻ ഇക്വിറ്റിയിൽ 90% ഉള്ള ഒരു ലിസ്റ്റഡ് ഫണ്ടിൽ 90% ഉള്ള fund of funds. SEBI കാറ്റഗറി കൊണ്ട് തീരുമാനിക്കാവുന്നിടത്ത് ഫണ്ട് തരം അതിൽ നിന്ന് എടുക്കുന്നു; നിങ്ങളുടെ ഫണ്ടിന്റെ സ്വന്തം രീതി പരിശോധിക്കുക.",
        setOff:
          "തട്ടിക്കിഴിക്കൽ (set-off): ഹ്രസ്വകാല നഷ്ടം ഏത് ക്യാപിറ്റൽ ഗെയിനും കുറയ്ക്കാം, ദീർഘകാല നഷ്ടം ദീർഘകാല നേട്ടം മാത്രം (സെക്ഷൻ 70, 74). നിരക്കുകൾ തമ്മിൽ നിയമം ക്രമം നിശ്ചയിക്കുന്നില്ല, അതിനാൽ നഷ്ടങ്ങൾ ഏറ്റവും ഉയർന്ന നിരക്കിനെതിരെ ആദ്യം തട്ടിക്കിഴിക്കുന്നു. മുൻ വർഷങ്ങളിൽ നിന്ന് മുന്നോട്ട് കൊണ്ടുവന്ന നഷ്ടങ്ങൾ ഉൾപ്പെടുത്തിയിട്ടില്ല.",
        cess: "ടാക്സിന്മേൽ 4% ഹെൽത്ത് ആൻഡ് എജ്യുക്കേഷൻ സെസ്. ഈ നേട്ടങ്ങൾക്ക് 15%-ൽ പരിമിതപ്പെടുത്തിയ സർചാർജ് ഉൾപ്പെടുത്തിയിട്ടില്ല.",
        act2025:
          "1 Apr 2026 മുതൽ Income-tax Act 2025, 1961-ലെ Act-ന് പകരം അതേ നിയമങ്ങൾ പുതിയ നമ്പറുകളിൽ കൊണ്ടുവരുന്നു: 111A സെക്ഷൻ 196, 112 എന്നത് 197, 112A എന്നത് 198, 50AA എന്നത് 76.",
