        body: "ഈ സൈറ്റിലെ ഓരോ കണക്കും ഇതിനകം സംഭവിച്ചതിനെയാണ് വിവരിക്കുന്നത്. അഞ്ച് വർഷം പ്രതിവർഷം 18% റിട്ടേൺ നൽകിയ ഫണ്ട് അഞ്ച് വർഷം പ്രതിവർഷം 18% നൽകിയ ഫണ്ടാണ്; ഇനിയും നൽകുന്ന ഫണ്ടല്ല. റിട്ടേൺ വിപണിയിൽ നിന്നാണ് വരുന്നത്, ഒരു മുൻകാല സംഖ്യ ഉണ്ടാക്കിയ വിപണി സാഹചര്യങ്ങൾ ആവശ്യാനുസരണം ആവർത്തിക്കാനാവില്ല. പ്രവചിക്കാനല്ല, ഒരു ഫണ്ട് എങ്ങനെ പെരുമാറി എന്ന് മനസ്സിലാക്കാൻ ഈ സംഖ്യകൾ ഉപയോഗിക്കുക - എങ്ങനെ ഇടിഞ്ഞു, എങ്ങനെ തിരിച്ചുകയറി, എത്ര സ്ഥിരതയുണ്ടായിരുന്നു, എന്ത് ചെലവായി. ഇവിടെ ഒന്നും ഉപദേശമല്ല, ഒന്നും പ്രവചനവുമല്ല.",
