        body: "ഒരു small-cap ഫണ്ടും liquid ഫണ്ടും താരതമ്യം ചെയ്യാനാവില്ല, അതിനാൽ ഇവിടെയുള്ള ഓരോ ആപേക്ഷിക സംഖ്യയും ഒരു ഫണ്ടിനെ അതിന്റെ സ്വന്തം SEBI സബ്-കാറ്റഗറിയിലെ ഫണ്ടുകളുമായി മാത്രം താരതമ്യം ചെയ്യുന്നു - Flexi Cap-നെ Flexi Cap-മായി, Small Cap-നെ Small Cap-മായി. ആ ഗ്രൂപ്പാണ് ഫണ്ടിന്റെ പിയർ ഫണ്ടുകൾ. ഈ സൈറ്റിൽ 'സമാന ഫണ്ടുകൾ' എന്ന് കാണുമ്പോൾ അതാണ് അർത്ഥം. പിയർ ശരാശരി ഫണ്ടിനെ തന്നെ കണക്കിൽ നിന്ന് ഒഴിവാക്കുന്നു, അതിനാൽ ഒരു വലിയ ഫണ്ടിനെ ഭാഗികമായി അതുമായി തന്നെ അളക്കുന്നില്ല. ന്യായമായ ശരാശരിക്ക് ഒരു സബ്-കാറ്റഗറിയിൽ ഫണ്ടുകൾ വളരെ കുറവാണെങ്കിൽ, ഏതാനും ഫണ്ടുകൾ കൊണ്ട് കണക്കാക്കുന്നതിന് പകരം താരതമ്യം ശൂന്യമായി വിടുന്നു.",
