        body: "ട്രെയിലിങ് 5 വർഷ റിട്ടേൺ കൃത്യം ഒരു വിൻഡോ മാത്രം അളക്കുന്നു: ഇന്ന് മുതൽ അഞ്ച് വർഷം പിന്നോട്ട്. തുടക്ക തീയതി ഏതാനും മാസം മാറ്റിയാൽ ഉത്തരം വൻതോതിൽ മാറാം, കാരണം നിങ്ങൾ വിപണിയുടെ താഴ്ചയിലോ ഉയർച്ചയിലോ ആണോ തുടങ്ങിയത് എന്നതിനെ ആശ്രയിച്ചിരിക്കുന്നു. റോളിങ് റിട്ടേൺ ഫണ്ടിന്റെ ചരിത്രത്തിലെ സാധ്യമായ ഓരോ 5 വർഷ വിൻഡോയും കണക്കാക്കി വ്യാപ്തി കാണിക്കുന്നു - സാധാരണ, ഏറ്റവും മോശം, ഏറ്റവും മികച്ചത്, എത്ര തവണ വിൻഡോ ലാഭത്തിൽ അവസാനിച്ചു. ഏറ്റവും മോശം വിൻഡോയാണ് സാധാരണയായി പേജിലെ ഏറ്റവും വിവരം നൽകുന്ന സംഖ്യ: ഭാഗ്യമില്ലാത്ത ഒരു നിക്ഷേപകന് യഥാർത്ഥത്തിൽ കിട്ടിയത് അതാണ്. ഒറ്റ ട്രെയിലിങ് സംഖ്യ ഇതെല്ലാം മറയ്ക്കുന്നു.",
