      "sip-vs-lumpsum": {
        term: "SIP vs ലംപ്സം",
        body: "മിക്കവരും ഒറ്റയടിക്കല്ല, മാസം തോറുമാണ് നിക്ഷേപിക്കുന്നത്, ഒരേ ഫണ്ടിൽ നിന്ന് രണ്ടും യഥാർത്ഥത്തിൽ വ്യത്യസ്ത റിട്ടേൺ നൽകുന്നു. ട്രെയിലിങ് റിട്ടേൺ അനുമാനിക്കുന്നത് നിങ്ങൾ ആദ്യ ദിവസം എല്ലാം നിക്ഷേപിച്ച് അവസാനം എല്ലാം പിൻവലിച്ചു എന്നാണ്. SIP റിട്ടേൺ എല്ലാ മാസവും ഒരു നിശ്ചിത തുക അനുമാനിക്കുന്നു, അതിനാൽ അടുത്തിടെ നിക്ഷേപിച്ച പണത്തിന് വളരാൻ കുറച്ച് സമയമേ കിട്ടിയുള്ളൂ, വർഷങ്ങൾക്ക് മുമ്പുള്ള പണത്തിന് ധാരാളം കിട്ടി. കാലയളവിന്റെ തുടക്കത്തിൽ വിപണി കുത്തനെ ഉയർന്നാൽ, ലംപ്സം കണക്ക് ഒരു മാസ നിക്ഷേപകന് യഥാർത്ഥത്തിൽ കിട്ടിയതിനേക്കാൾ വളരെ മികച്ചതായി കാണും. രണ്ടും ഇവിടെ വേറെ വേറെ ലേബൽ ചെയ്ത് കാണിക്കുന്നു.",
      },
