    "Turnover is the change between two consecutive monthly portfolios, so it needs at least two disclosure months for this scheme. Only one is stored.":
      "ടേൺഓവർ തുടർച്ചയായ രണ്ട് പ്രതിമാസ പോർട്ട്ഫോളിയോകൾ തമ്മിലുള്ള മാറ്റമാണ്, അതിനാൽ ഈ സ്കീമിന് കുറഞ്ഞത് രണ്ട് വെളിപ്പെടുത്തൽ മാസങ്ങൾ വേണം. ഒന്ന് മാത്രമേ സൂക്ഷിച്ചിട്ടുള്ളൂ.",
